// Parse and VALIDATE the model's answer. An LLM will occasionally return
// prose, a code fence, or a category nobody defined, and writing that
// straight into the database would silently break every report built on it.
// Anything that does not pass is skipped and reported, never guessed at.
const allowed = $('Get untagged people').first().json.allowed_categories;
const person = $('Loop over people').first().json.person;
const out = [];

for (const item of $input.all()) {
  const response = item.json;

  // API-level failure (rate limit, overload). Leave the person untagged: the
  // next scheduled run picks them up again because the endpoint is idempotent.
  if (response.error || !response.content) {
    out.push({ json: { ok: false, person_id: person.person_id,
      reason: 'api_error: ' + JSON.stringify(response.error || response).slice(0, 200) } });
    continue;
  }

  const text = (response.content || [])
    .filter(block => block.type === 'text').map(block => block.text).join('').trim();

  // Strip a ```json fence if the model added one anyway.
  const cleaned = text.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (error) {
    out.push({ json: { ok: false, person_id: person.person_id,
      reason: 'unparseable_json', raw: text.slice(0, 200) } });
    continue;
  }

  const category = String(parsed.category || '').trim().toLowerCase();
  if (!allowed.includes(category)) {
    out.push({ json: { ok: false, person_id: person.person_id,
      reason: 'category_not_allowed', got: parsed.category } });
    continue;
  }

  let confidence = Number(parsed.confidence);
  if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
    confidence = null;
  }

  out.push({ json: {
    ok: true,
    person_id: person.person_id,
    person_name: person.full_name,
    category,
    confidence,
    rationale: String(parsed.rationale || '').slice(0, 300),
    key_skills: Array.isArray(parsed.key_skills) ? parsed.key_skills.join(', ')
                                                 : String(parsed.key_skills || ''),
    model: response.model || 'claude-sonnet-5',
    input_tokens: response.usage ? response.usage.input_tokens : null,
    output_tokens: response.usage ? response.usage.output_tokens : null
  } });
}

return out;

